import React, { useState } from 'react';
import axios from 'axios';

const FacultyBooking = ({ user }) => {
    const [duration, setDuration] = useState("");
    const [reason, setReason] = useState("");
    const [message, setMessage] = useState("");

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const res = await axios.post('http://localhost:8082/faculty/book', {
                faculty_id: user.userid,
                faculty_name: user.fname + " " + user.lname,
                department: "IT Department", // Fetch dynamically if needed
                requested_duration: duration,
                reason: reason
            });
            setMessage("Booking request submitted successfully!");
        } catch (error) {
            console.error("Error submitting booking request:", error);
            setMessage("Error submitting request");
        }
    };

    return (
        <div>
            <h2>Faculty Quarters Booking</h2>
            <form onSubmit={handleSubmit}>
                <label>Requested Duration:</label>
                <input type="text" value={duration} onChange={(e) => setDuration(e.target.value)} required />
                
                <label>Reason:</label>
                <textarea value={reason} onChange={(e) => setReason(e.target.value)} required />

                <button type="submit">Submit Request</button>
            </form>
            {message && <p>{message}</p>}
        </div>
    );
};

export default FacultyBooking;
